 static function audit():array {
  self::migrate();$report=['scope'=>'RETAINED_OBSERVATIONS_ONLY','checked_at'=>time(),'retention_limit'=>500,'observations'=>0,'from'=>null,'to'=>null,'methods'=>[]];
  // Extract only evaluation results, never snapshots, account details or API payloads.
  $q=db()->query("SELECT created,json_extract(payload,'$.result.methods') AS methods FROM pattern_observations ORDER BY id");
  while($row=$q->fetch(PDO::FETCH_ASSOC)){
   $at=(int)$row['created'];$report['observations']++;$report['from']=min($report['from']??$at,$at);$report['to']=max($report['to']??$at,$at);
   foreach(json_decode($row['methods']??'{}',true)??[] as $id=>$m){if(($m['account_id']??0)!==0)continue;$key=($m['exchange']??'wallex').':'.($m['symbol']??'BTCUSDT').':'.$id;
    $v=$report['methods'][$key]??['checks'=>0,'sufficient'=>0,'unavailable'=>0,'confirmed'=>0,'reasons'=>[],'last_checked'=>null,'last_reason'=>null];$v['checks']++;$v['sufficient']+=(int)(($m['data_status']??'')==='SUFFICIENT'&&($m['pattern_status']??'')!=='UNAVAILABLE');$v['unavailable']+=(int)(($m['pattern_status']??'')==='UNAVAILABLE');$v['confirmed']+=(int)(($m['pattern_status']??'')==='PATTERN_CONFIRMED');$reason=$m['reason']??'';$v['reasons'][$reason]=($v['reasons'][$reason]??0)+1;$v['last_checked']=$at;$v['last_reason']=$reason;$report['methods'][$key]=$v;
   }
  }return $report;
 }
 static function migrate():void {db()->exec("CREATE TABLE IF NOT EXISTS pattern_market_runtime(market TEXT PRIMARY KEY,state TEXT NOT NULL,last_checked INTEGER,last_result TEXT);");db()->exec('CREATE TABLE IF NOT EXISTS pattern_runtime(id INTEGER PRIMARY KEY CHECK(id=1),state TEXT NOT NULL,last_checked INTEGER,last_result TEXT); INSERT OR IGNORE INTO pattern_runtime(id,state) VALUES(1,\'{}\'); CREATE TABLE IF NOT EXISTS pattern_signals(id TEXT PRIMARY KEY,created INTEGER NOT NULL,payload TEXT NOT NULL); CREATE TABLE IF NOT EXISTS pattern_execution(id TEXT PRIMARY KEY,observed INTEGER NOT NULL,payload TEXT NOT NULL); CREATE TABLE IF NOT EXISTS pattern_events(id INTEGER PRIMARY KEY AUTOINCREMENT,signal_id TEXT NOT NULL,event TEXT NOT NULL,created INTEGER NOT NULL,payload TEXT NOT NULL,UNIQUE(signal_id,event)); CREATE TABLE IF NOT EXISTS pattern_observations(id INTEGER PRIMARY KEY AUTOINCREMENT,created INTEGER NOT NULL,payload TEXT NOT NULL);');}
 static function runtimeWhere():string {return ' market='.db()->quote(MarketScope::key());}
