 static function save(array $input):array {$c=PatternConfig::validate($input);$lock=fopen(self::lockPath(),'c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new RuntimeException('Pattern scanner busy; retry');try{self::migrate();$old=self::config();$state=json_decode(self::runtime()['state'],true);foreach($c['methods'] as $id=>$p)if($old['enabled']!==$c['enabled']||$old['methods'][$id]!=$p)unset($state[$id]);MarketScope::set('pattern_config',encode($c));db()->prepare('UPDATE pattern_market_runtime SET state=?,last_result=NULL WHERE '.self::runtimeWhere())->execute([encode($state)]);return $c;}finally{flock($lock,LOCK_UN);fclose($lock);}}
 static function persist(array $snapshot,?array $c=null,?array $breakConfig=null):array {
  self::migrate();$c??=self::config();$breakConfig??=ScannerService::config();$row=self::runtime();$before=json_decode($row['state'],true);$state=$before;$now=$snapshot['observed_at'];
