  foreach($r['methods'] as $id=>&$card){
   $stats=$before[$id]['monitoring']??['since'=>$now,'checks'=>0,'evaluated'=>0,'unavailable'=>0,'confirmed_signals'=>0,'evaluated_candles'=>0,'last_evaluated_close'=>null];$stats['checks']++;
   $valid=$card['data_status']==='SUFFICIENT'&&$card['pattern_status']!=='UNAVAILABLE'&&isset($state[$id]['last_evaluation']);$stats['evaluated']+=(int)$valid;$stats['unavailable']+=(int)($card['pattern_status']==='UNAVAILABLE');$close=intdiv($now,900)*900;
   if($valid&&$close!==$stats['last_evaluated_close']){$stats['evaluated_candles']++;$stats['last_evaluated_close']=$close;}
   $card['monitoring']=$state[$id]['monitoring']=$stats;
  }unset($card);
  db()->beginTransaction();try{$q=db()->prepare('UPDATE pattern_market_runtime SET state=?,last_checked=?,last_result=? WHERE '.self::runtimeWhere().' AND state=?');$q->execute([encode($state),$now,encode($r),$row['state']]);if(!$q->rowCount()){db()->rollBack();return ['status'=>'CONCURRENT_UPDATE_DISCARDED','signals'=>[]];}
   $emitted=[];foreach($r['signals'] as &$p){$q=db()->prepare('INSERT OR IGNORE INTO pattern_signals VALUES(?,?,?)');$q->execute([$p['id'],$now,encode($p)]);if(!$q->rowCount()){$existing=db()->prepare('SELECT payload FROM pattern_signals WHERE id=?');$existing->execute([$p['id']]);$original=json_decode($existing->fetchColumn(),true);$state[$p['strategy_id']]['last_signal']=$original;$r['methods'][$p['strategy_id']]['last_signal']=$original;continue;}
