    $payload=$p;$payload['strategy_method_id']=$p['strategy_id'];$payload['strategy_id']=$strategy;$payload['type']='scanner_pattern';$payload['name']='تأیید الگوی نموداری · '.PatternConfig::name($p['strategy_id']);$payload['action']=$p['direction'];$payload['price']=$p['reference_price'];$payload['event']='PATTERN_CONFIRMED';$payload['event_time']=$p['confirmation_candle_close'];$payload['message']=PatternEngine::message($p);$payload['analysis_sources']=[];$payload['sent_at']=$now;
