   }unset($p);foreach($emitted as $signal){$id=$signal['strategy_id'];$state[$id]['monitoring']['confirmed_signals']++;$r['methods'][$id]['monitoring']=$state[$id]['monitoring'];}$r['signals']=$emitted;db()->prepare('UPDATE pattern_market_runtime SET state=?,last_result=? WHERE '.self::runtimeWhere())->execute([encode($state),encode($r)]);
   db()->prepare('INSERT INTO pattern_observations(created,payload) VALUES(?,?)')->execute([$now,encode(['snapshot'=>$snapshot,'config'=>$c,'break_config'=>$breakConfig,'state_before'=>$before,'state_after'=>$state,'result'=>$r])]);
   db()->exec('DELETE FROM pattern_observations WHERE id NOT IN (SELECT id FROM pattern_observations ORDER BY id DESC LIMIT 500)');while((int)db()->query('SELECT coalesce(sum(length(payload)),0) FROM pattern_observations')->fetchColumn()>33554432)db()->exec('DELETE FROM pattern_observations WHERE id IN (SELECT id FROM pattern_observations ORDER BY id LIMIT 20)');db()->commit();return $r;
  }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
 }
 static function tick(?Wallex $api=null,?int $at=null):array {self::migrate();$c=self::config();if(!$c['enabled']||!array_filter($c['methods'],fn($p)=>$p['enabled']))return ['status'=>'DISABLED'];$lock=fopen(self::lockPath(),'c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB)){if($lock)fclose($lock);return ['status'=>'BUSY'];}
  try{$now=$at??time();if($now-(int)MarketScope::setting('pattern_last_attempt','0')<$c['interval_seconds'])return ['status'=>'NOT_DUE'];MarketScope::set('pattern_last_attempt',(string)$now);$breakConfig=ScannerService::config();$cache=json_decode(MarketScope::setting('pattern_cache','{}'),true);try{$snapshot=PatternData::fetch($api??MarketData::provider(MarketScope::current()['exchange'],microtime(true)+18),$c,$breakConfig,$now,$cache);MarketScope::set('pattern_cache',encode($snapshot));unset($snapshot['pages'],$snapshot['pages_boundary']);}catch(Throwable $e){$snapshot=MarketScope::current()+['provider'=>MarketScope::current()['exchange'],'observed_at'=>$now,'received_at'=>$now,'bars'=>[],'data_error'=>$e->getMessage()];}return self::persist($snapshot,$c,$breakConfig);
  }finally{flock($lock,LOCK_UN);fclose($lock);}
 }
