 static function view():array {self::migrate();$row=self::runtime();$signals=array_map(fn($r)=>json_decode($r['payload'],true),db()->query("SELECT payload FROM pattern_signals WHERE coalesce(json_extract(payload,'$.exchange'),'wallex')=".db()->quote(MarketScope::current()['exchange'])." AND json_extract(payload,'$.symbol')=".db()->quote(MarketScope::current()['symbol'])." AND coalesce(json_extract(payload,'$.account_id'),0)=".MarketScope::current()['account_id']." ORDER BY created DESC,rowid DESC LIMIT 200")->fetchAll(PDO::FETCH_ASSOC));$q=db()->prepare('SELECT payload FROM pattern_execution WHERE id=?');foreach($signals as &$signal){$q->execute([$signal['id']]);$exec=$q->fetchColumn();if($exec)$signal['current_execution']=json_decode($exec,true);}unset($signal);$c=self::config();$r=$row['last_result']?json_decode($row['last_result'],true):null;$savedState=json_decode($row['state'],true);$methods=$r['methods']??[];foreach($c['methods'] as $id=>$p)if(!isset($methods[$id]))$methods[$id]=MarketScope::current()+['strategy_id'=>$id,'name'=>PatternConfig::name($id),'enabled'=>$c['enabled']&&$p['enabled'],'data_status'=>'NOT_EVALUATED','pattern_status'=>$c['enabled']&&$p['enabled']?'WAITING_DATA':'DISABLED','execution_status'=>'NOT_EVALUATED','last_signal'=>$savedState[$id]['last_signal']??null,'reason'=>'هنوز داده بررسی نشده است.'];
